"use strict";
// Town NPCs like the JX1 client: every Thành thị / Thôn trang shows its NPCs (npcdata.js, generated by
// tools/jxmap/npcs.py from the JX1 paks), depth-sorted with the map objects, with their JX1 stand
// animation + shadow, name and title. Click / tap an NPC: the hero walks up to it (navGo) and a JX1-style
// dialog opens with the NPC's line and options mapped to the game's features:
//   shop    -> openNpcShop(saleId, npc) (js/npcshop.js) or the town shop (shopModal)
//   storage / bank -> Kho chung (stashModal)
//   xaphu   -> JX1 carriage (Station.txt / StationPrice.txt prices) + the Thần Hành Phù picker
//   guard / talk -> dialog only; critters are ambient.
// Only the current town's NPCs exist (built on town entry, dropped on leave). Hooks: jxmSort (adds NPC
// entries {x, y, jo: {npc}}), jxmDrawObj (draws them), drawShadows, townTick (small collision), pointer.
const NPCV = { data: null, st: 0, key: "", list: [], hover: null, tgt: null, open: null, t: 0, shOk: !1 };
const NPC_R = 16, // collision radius (screen px, iso: y counts double)
  NPC_TALK = 72, // the dialog opens when the hero is this close to the target NPC
  NPC_NAME = "#ffffff", // JX1 (KgameWorldVN.cpp): dialog NPC names keep the default white
  NPC_TITLE = "#f3d88a",
  NPC_V = ((document.currentScript && /[?&]v=([^&]+)/.exec(document.currentScript.src)) || [])[1] || "1";

function npcData(cb) {
  if (window.JNPC) return (npcInit(), cb && cb(), window.JNPC);
  if (NPCV.st) return null;
  NPCV.st = 1;
  const s = document.createElement("script");
  s.src = `npcdata.js?v=${NPC_V}`;
  s.async = !0;
  s.onload = () => (npcInit(), cb && cb());
  s.onerror = () => (NPCV.st = 2);
  document.head.appendChild(s);
  return null;
}
function npcInit() {
  const J = window.JNPC;
  if (!J || NPCV.data) return;
  NPCV.data = J;
  if (typeof W == "object" && W.anim) for (const k in J.anim) W.anim[k] || (W.anim[k] = J.anim[k]);
}
// shadow sheets go into shadow.js' table once it is loaded (before any NPC shadow is drawn)
function npcShReady() {
  if (NPCV.shOk) return !0;
  if (typeof SHD == "undefined" || !SHD || !SHD.a || !NPCV.data) return !1;
  Object.assign(SHD.a, NPCV.data.sh || {});
  return (NPCV.shOk = !0);
}
// The town currently shown with its full map, or "".
function npcMapId() {
  if (!R.town || typeof JXM != "object" || !JXM.cur || !OBS.g || !OBS.g.jm) return "";
  return String(JXM.cur.id) === String(W.town.id) ? String(JXM.cur.id) : "";
}
// (Re)build the NPC list when the shown town changes.
function npcSync() {
  const id = npcMapId();
  if (id === NPCV.key) return NPCV.list;
  if (id && !npcData(() => (NPCV.key = "?"))) return (NPCV.list = []);
  NPCV.key = id;
  NPCV.hover = NPCV.tgt = null;
  npcClose();
  const rows = (id && NPCV.data && NPCV.data.maps[id]) || [];
  NPCV.list = rows.map((r, i) => Object.assign({}, r, { i, tt: r.t || "", t: Math.random() * 3, d: r.d || 0 }));
  return NPCV.list;
}
const npcAnim = (n) => {
  const a = W.anim && W.anim[n.a];
  return a && a.st;
};
// Sprite rect (screen px) for hit tests.
function npcRect(n) {
  const a = npcAnim(n);
  if (!a) return [n.x - 16, n.y - 60, 32, 64];
  const w = Math.max(28, a.w * 0.7),
    h = Math.max(30, Math.min(a.h, a.ay + 6));
  return [n.x - w / 2, n.y - a.ay - 2, w, h + 6];
}
function npcAt(x, y) {
  let best = null;
  for (const n of NPCV.list) {
    if (n.c) continue;
    const [rx, ry, w, h] = npcRect(n);
    x >= rx && x <= rx + w && y >= ry && y <= ry + h && (!best || n.y > best.y) && (best = n);
  }
  return best;
}
function npcVisible() {
  const pad = 200,
    out = [];
  for (const n of NPCV.list)
    n.x > CAM.x - pad && n.x < CAM.x + AR.w + pad && n.y > CAM.y - 60 && n.y < CAM.y + AR.h + pad * 1.5 && out.push(n);
  return out;
}
// ---- drawing
function npcDraw(c, n) {
  const k = n.a,
    hov = NPCV.hover === n || NPCV.tgt === n || (NPCV.open && NPCV.open.n === n),
    h = drawAnim(k, "st", n.d, n.t, n.x, n.y, 1, 1);
  if (h && hov) {
    // JX1 brightens the NPC under the cursor
    c.save();
    c.globalCompositeOperation = "lighter";
    drawAnim(k, "st", n.d, n.t, n.x, n.y, 1, 0.35);
    c.restore();
  }
  if (n.c && !hov) return;
  const top = n.y - (h ? Math.min(h, 140) : 60) - 4;
  label(n.x, top, n.n, NPC_NAME, 12, -1, "", n.tt && n.tt.toLowerCase() !== n.n.toLowerCase() ? n.tt : "", NPC_TITLE);
}
function npcShadows(c) {
  if (S.shadow === !1 || !npcShReady() || typeof shAnim != "function") return;
  for (const n of npcVisible()) shAnim(c, n.a, "st", n.d, n.t, n.x, n.y, 1, 1);
}
// ---- input
function npcWorldPt(e) {
  const r = CV.getBoundingClientRect(),
    s = typeof uiScale == "function" ? uiScale() : 1;
  return [(e.clientX - r.left) / s + CAM.x, (e.clientY - r.top) / s + CAM.y];
}
function npcPointerDown(e) {
  if (!NPCV.list.length || e.target !== CV || (e.button != null && e.button > 0)) return;
  const [x, y] = npcWorldPt(e),
    n = npcAt(x, y);
  if (!n) return;
  e.stopPropagation();
  e.preventDefault();
  npcGoTo(n);
}
function npcPointerMove(e) {
  if (!NPCV.list.length || e.pointerType === "touch") return;
  const [x, y] = npcWorldPt(e),
    n = npcAt(x, y);
  NPCV.hover !== n && ((NPCV.hover = n), (CV.style.cursor = n ? "pointer" : ""));
}
// Walk up to n (like JX1), then talk.
function npcGoTo(n) {
  npcClose();
  NPCV.tgt = n;
  INPUT.target = npcFront(n);
  H._nav = null;
  typeof uiSfx == "function" && uiSfx("use");
}
// a walkable point just in front of the NPC (south), else beside it
function npcFront(n) {
  for (const [dx, dy] of [
    [0, 26],
    [-30, 16],
    [30, 16],
    [0, -22],
    [-40, 0],
    [40, 0],
  ])
    if (typeof obsWalk != "function" || obsWalk(n.x + dx, n.y + dy)) return { x: n.x + dx, y: n.y + dy };
  return { x: n.x, y: n.y + 26 };
}
const npcDist = (a, b) => Math.hypot(a.x - b.x, (a.y - b.y) * 2);
function npcTick(dt) {
  npcSync();
  if (!NPCV.list.length) return;
  for (const n of NPCV.list) n.t += dt;
  // small collision: the hero can't stand inside an NPC
  for (const n of NPCV.list) {
    if (n.c) continue;
    const dx = H.x - n.x,
      dy = (H.y - n.y) * 2,
      L = Math.hypot(dx, dy);
    if (L < NPC_R && L > 0.01) {
      const k = NPC_R / L;
      typeof obsMove == "function" ? obsMove(H, n.x + dx * k, n.y + (dy * k) / 2) : ((H.x = n.x + dx * k), (H.y = n.y + (dy * k) / 2));
    }
  }
  const t = NPCV.tgt;
  if (!t) return;
  if (!INPUT.target || npcDist(H, t) <= NPC_TALK) {
    const near = npcDist(H, t) <= NPC_TALK * 1.6;
    INPUT.target = null;
    NPCV.tgt = null;
    near ? npcTalk(t) : toast(`Không tới được ${t.n}`);
  }
}
// ---- dialog (JX1 Say box: name, text, option lines)
const NPC_CSS = `
#npcDlg{position:absolute;left:50%;bottom:118px;transform:translateX(-50%);z-index:7;width:min(460px,calc(100% - 24px));
 box-sizing:border-box;padding:10px 14px 8px;border:1px solid #8a6d2e;border-radius:4px;
 background:linear-gradient(#1d150bf2,#110c06f2);box-shadow:0 0 0 1px #000,0 6px 18px #000a;color:#e8dcc0;font-size:13px;line-height:1.45}
#npcDlg[hidden]{display:none}
#npcDlg b.nm{display:block;color:#f3d88a;font-size:14px;margin-bottom:4px}
#npcDlg b.nm small{color:#a89a74;font-weight:normal;font-size:11px;margin-left:6px}
#npcDlg p{margin:0 0 6px}
#npcDlg .op{display:block;width:100%;text-align:left;background:none;border:0;padding:3px 4px;color:#9fd4ff;font:inherit;cursor:pointer}
#npcDlg .op:hover,#npcDlg .op:focus{color:#fff;background:#ffffff14;outline:none}
#npcDlg .op.x{color:#c8b890}
#npcDlg .op[disabled]{color:#6d6656;cursor:default}
#npcDlg .op i{font-style:normal;color:#d8c27a;float:right}
`;
function npcBox() {
  let el = $("#npcDlg");
  if (el) return el;
  const b = document.getElementById("battle");
  if (!b) return null;
  const st = document.createElement("style");
  st.textContent = NPC_CSS;
  document.head.appendChild(st);
  el = document.createElement("div");
  el.id = "npcDlg";
  el.hidden = !0;
  el.addEventListener("pointerdown", (e) => e.stopPropagation());
  b.appendChild(el);
  return el;
}
function npcClose() {
  const el = $("#npcDlg");
  el && (el.hidden = !0);
  NPCV.open = null;
}
function npcShow(n, text, ops) {
  const el = npcBox();
  if (!el) return;
  NPCV.open = { n };
  el.innerHTML =
    `<b class="nm">${esc(n.n)}${n.tt && n.tt.toLowerCase() !== n.n.toLowerCase() ? `<small>${esc(n.tt)}</small>` : ""}</b><p>${esc(text || "...")}</p>` +
    ops
      .map(
        (o, i) =>
          `<button class="op${o.x ? " x" : ""}" data-i="${i}"${o.dis ? " disabled" : ""}>${esc(o.t)}${o.r ? `<i>${esc(o.r)}</i>` : ""}</button>`,
      )
      .join("");
  el.hidden = !1;
  el.querySelectorAll(".op").forEach((b) => {
    b.onclick = () => {
      const o = ops[+b.dataset.i];
      o && !o.dis && (o.keep || npcClose(), o.f && o.f());
    };
  });
}
const npcBye = () => ({ t: "Kết thúc đối thoại", x: 1 });
function npcTalk(n) {
  // the NPC turns to the hero (sheets with 8 directions)
  const a = npcAnim(n);
  a && a.d > 1 && !n.c && (n.d = dirOf(H.x - n.x, H.y - n.y));
  H.dir = dirOf(n.x - H.x, n.y - H.y);
  const ops = [];
  switch (n.k) {
    case "shop":
      ops.push({ t: "Giao dịch", f: () => npcShop(n) });
      /dược|thuốc/i.test(n.n + n.tt) &&
        ops.push({ t: "Trị thương", f: () => ((R.life = R.P.life), (R.mana = R.P.mana), toast("Đã hồi phục sinh lực, nội lực")) });
      break;
    case "storage":
      ops.push({ t: "Mở rương (Kho chung)", f: () => stashModal() });
      break;
    case "bank":
      ops.push({ t: "Gửi / rút đồ (Kho chung)", f: () => stashModal() });
      break;
    case "xaphu":
      return npcXaPhu(n);
  }
  ops.push(npcBye());
  npcShow(n, n.l || "Khách quan có việc gì không?", ops);
}
function npcShop(n) {
  if (typeof openNpcShop == "function") return openNpcShop(npcShopFor(n), n);
  shopModal();
}
// Cities without their own merchant script borrow Lâm An's Sale ids in npcdata.js; prefer this town's own
// shop of the same kind (buysell.txt layout, js/npcshop.js) when the borrowed shop belongs to another town.
function npcShopFor(n) {
  const sh = window.NPC_SHOPS && NPC_SHOPS[n.s],
    town = W.town && W.town.id;
  if (!sh || town == null || typeof npcTownShopId != "function") return n.s;
  if (sh.maps && sh.maps.map(Number).includes(Number(town))) return n.s;
  return npcTownShopId(sh.kind, town) || n.s;
}
// ---- Xa phu: JX1 carriage between stations (StationPrice.txt), Thần Hành Phù for anywhere else
function npcXaPhu(n) {
  const id = NPCV.key,
    P = (NPCV.data.price || {})[id] || {},
    ops = [];
  for (const k of Object.keys(P).sort((a, b) => P[a] - P[b])) {
    const d = typeof thDest == "function" && thDest(k);
    if (!d || !d.safe) continue;
    const ok = typeof thAvail != "function" || thAvail(d);
    ops.push({ t: `Đi ${d.n}`, r: ok ? `${fmtL(P[k])} lượng` : "chưa có bản đồ", dis: !ok, f: () => npcRide(d, P[k]) });
  }
  ops.push({ t: "Nơi khác (Thần Hành Phù)", f: () => (typeof thUse == "function" ? thUse() : toast("Không dùng được")) });
  ops.push(npcBye());
  npcShow(n, n.l || "Ngồi xe của ta vừa nhanh vừa an toàn, khách quan muốn đi đâu?", ops);
}
// Ride to town d: land next to its Xa phu (the JX1 station point), pay the JX1 price.
function npcRide(d, price) {
  if (typeof thBlocked == "function" && thBlocked()) return toast(thBlocked());
  if (S.gold < price) return toast("Không đủ ngân lượng");
  const rows = (NPCV.data.maps[String(d.id)] || []).filter((r) => r.k === "xaphu"),
    st = rows.find((r) => r.st === 0) || rows[0],
    pt = st ? npcFront(st) : { x: d.x, y: d.y },
    prev = { id: W.town.id, n: W.town.n, bg: W.town.bg },
    prevT = S.thTown;
  thSetTown(d);
  jxmLand(d.id, st ? st.x + 40 : pt.x, st ? st.y + 30 : pt.y);
  JXM.landPending = String(d.id);
  if (!thToTown()) return (Object.assign(W.town, prev), prevT == null ? delete S.thTown : (S.thTown = prevT));
  S.gold -= price;
  R.banner = { t: 2.2, text: d.n, sub: `Xa phu · ${fmtL(price)} lượng` };
  $("#townName") && ($("#townName").textContent = d.n);
  log(`Ngồi xe ngựa tới <b>${esc(d.n)}</b> (−${fmtL(price)} lượng).`);
  typeof uiSfx == "function" && uiSfx("use");
  save();
  refresh();
}

// ---- install hooks (global functions are wrapped by name, like thanhanh.js)
function npcInstall() {
  if (typeof jxmSort == "function") {
    const o = jxmSort;
    jxmSort = function (list) {
      try {
        npcSync();
        if (NPCV.list.length) list = list.concat(npcVisible().map((n) => ({ x: n.x, y: n.y, jo: { npc: n } })));
      } catch (e) {
        console.warn("npc", e);
      }
      return o.call(this, list);
    };
  }
  if (typeof jxmDrawObj == "function") {
    const o = jxmDrawObj;
    jxmDrawObj = function (c, ob) {
      return ob && ob.npc ? npcDraw(c, ob.npc) : o.apply(this, arguments);
    };
  }
  if (typeof drawShadows == "function") {
    const o = drawShadows;
    drawShadows = function (c) {
      const r = o.apply(this, arguments);
      try {
        NPCV.list.length && npcShadows(c);
      } catch {}
      return r;
    };
  }
  if (typeof townTick == "function") {
    const o = townTick;
    townTick = function (t) {
      const r = o.apply(this, arguments);
      try {
        npcTick(t);
      } catch (e) {
        console.warn("npc", e);
      }
      return r;
    };
  }
  if (typeof backFromTown == "function") {
    const o = backFromTown;
    backFromTown = function () {
      npcClose();
      NPCV.tgt = null;
      return o.apply(this, arguments);
    };
  }
  window.addEventListener("pointerdown", (e) => R.town && npcPointerDown(e), !0);
  typeof CV != "undefined" && CV && CV.addEventListener("pointermove", (e) => R.town && npcPointerMove(e));
  window.addEventListener("keydown", (e) => {
    e.key === "Escape" && NPCV.open && npcClose();
  });
}
document.readyState === "loading" ? document.addEventListener("DOMContentLoaded", npcInstall) : setTimeout(npcInstall, 0);
